<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\DTO\Request\CreateQuestionCommentRequestDto;use App\Application\QuestionLearning\DTO\Response\QuestionCommentResponseDto;use App\Application\QuestionLearning\Mapper\QuestionCommentResponseMapper;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Entity\QuestionComment;use App\Domain\QuestionLearning\Repository\QuestionCommentRepositoryInterface;
final readonly class CreateQuestionCommentService { public function __construct(private FrozenQuestionReaderInterface $questions, private QuestionCommentRepositoryInterface $comments, private QuestionCommentResponseMapper $mapper) {} public function execute(string $userId, CreateQuestionCommentRequestDto $request, \DateTimeImmutable $now): QuestionCommentResponseDto { if (count($this->questions->findByIds([$request->questionId])) !== 1) { throw new \DomainException('Questão não encontrada.'); } if ($request->parentId !== null && $this->comments->findForQuestion($request->parentId, $request->questionId) === null) { throw new \DomainException('Comentário pai não encontrado na questão.'); } $comment = new QuestionComment($this->uuid(), $request->questionId, $userId, $request->parentId, $request->content, $now, $now); $this->comments->save($comment); return $this->mapper->toResponse($comment); } private function uuid(): string { $bytes = random_bytes(16); $bytes[6] = chr((ord($bytes[6]) & 15) | 64); $bytes[8] = chr((ord($bytes[8]) & 63) | 128); return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)); } }
